  "LV {lv}": "LV {lv}",
  "{name} erreicht LV {lv}!": "{name} artık LV {lv}!",
  "Geschlüpft: {what}": "Yumurtadan çıktı: {what}",
  "Ein schillernder {name}! (1 zu 100)": "Yanardöner bir {name}! (100'de 1)",
  "Wähle zwei Begleiter.": "İki yoldaş seç.",
