  "Begleiter-Ausrüstung: {n} ({r})": "Yoldaş ekipmanı: {n} ({r})",
  "BEGLEITER-EI!": "YUMURTA!",
  "{egg}! Bring es ins Brutnest im Versteck.": "{egg}! Onu sığınaktaki Kuluçka Yuvası'na götür.",
  "Ein Begleiter-Ei! Dein Brutnest ist voll – dafür +1 Glücksmünze.": "Bir yoldaş yumurtası! Kuluçkan dolu – onun yerine +1 Şans Sikkesi.",
  "SCHILD": "KALKAN",
  "Nestmutter Gunda": "Yuva Anası Gunda",
  "Wärme, Futter, Zuwendung. Fehlt eins davon, schläft das Küken im Ei einfach weiter.": "Sıcaklık, yem, sevgi. Biri eksik olursa yumurtadaki yavru uyumaya devam eder.",
  "Sind alle drei Bedürfnisse gut gefüllt, wächst ein Ei anderthalbmal so schnell.": "Üç ihtiyacın üçü de iyice doluysa yumurta bir buçuk kat hızlı büyür.",
  "Streichle die Eier ruhig. Die spüren das. Wirklich.": "Yumurtaları okşamaktan çekinme. Hissederler. Gerçekten.",
  "Aus einem schmutzigen Ei schlüpft meist eine Schnecke. Aber man liebt sie trotzdem.": "Kirli bir yumurtadan genelde salyangoz çıkar. Ama yine de sevilir.",
  "Ein mythisches Ei braucht Tage. Und Sternenstaub. Und Geduld. Vor allem Geduld.": "Mitik bir yumurta günler ister. Bir de yıldız tozu. Bir de sabır. En çok da sabır.",
  "Brutnest: Ein Ei ist bereit zum Schlüpfen!": "Kuluçka Yuvası: Bir yumurta çatlamaya hazır!",
  "Brutnest: {n} Eier sind bereit zum Schlüpfen!": "Kuluçka Yuvası: {n} yumurta çatlamaya hazır!",
  "Brutnest: Ein Ei braucht dich – es wächst gerade nicht.": "Kuluçka Yuvası: Bir yumurtanın sana ihtiyacı var – şu an büyümüyor.",
  "Brutnest: {n} Eier brauchen dich – sie wachsen gerade nicht.": "Kuluçka Yuvası: {n} yumurtanın sana ihtiyacı var – şu an büyümüyorlar.",
  "BEREIT": "HAZIR",
  "Ein Ei! Das hast du dem Boss abgenommen? Bring es zu mir ins Brutnest – ich wohne jetzt im Versteck.": "Bir yumurta! Bunu bosstan mı aldın? Onu bana, Kuluçka Yuvası'na getir – artık sığınakta yaşıyorum.",
  "Ein Ei! Wo hast du das denn gefunden? Bring es zu mir ins Brutnest – ich wohne jetzt im Versteck.": "Bir yumurta! Bunu nerede buldun? Onu bana, Kuluçka Yuvası'na getir – artık sığınakta yaşıyorum.",
  "Halt es warm, füttere es und schenk ihm Zuwendung. Dann wächst es – auch während du unterwegs bist.": "Onu sıcak tut, besle ve ona sevgi göster. Böylece büyür – sen yoldayken bile.",
  "Irgendwann schlüpft daraus dein erster Begleiter. Komm, ich zeig dir das Nest.": "Bir gün ondan ilk yoldaşın çıkacak. Gel, sana yuvayı göstereyim.",
  "Ich bin Gunda und kümmere mich ab jetzt um das Brutnest im Versteck.": "Ben Gunda. Bundan sonra sığınaktaki Kuluçka Yuvası'yla ben ilgileneceğim.",
  "Eier schlüpfen nicht mehr von allein: Halt sie warm, füttere sie und schenk ihnen Zuwendung. Dann wachsen sie, auch während du unterwegs bist.": "Yumurtalar artık kendi kendine çatlamıyor: Onları sıcak tut, besle ve onlara sevgi göster. Böylece sen yoldayken bile büyürler.",
  "DEIN ERSTES EI": "İLK YUMURTAN",
  "NEU: DAS BRUTNEST": "YENİ: KULUÇKA YUVASI",
