  "Fällst du in den Verlorenen Landen, rettet dein Begleiter, was in seinem Beutel liegt. Seltenere Arten tragen mehr, das Talent „Große Taschen“ gibt weitere Plätze.": "Kayıp Diyarlar'da düşersen yoldaşın çantasındakileri kurtarır. Daha nadir türler daha fazla taşır, “Büyük Cepler” becerisi ek yer verir.",
  "Alles herausnehmen": "Hepsini çıkar",
