  "EIER {n}/{max}": "YUMURTALAR {n}/{max}",
  "Noch keine Eier. Das erste gibt es vom ersten Boss der Geschichte, weitere von Bossen, der Drachentruhe, aus den Verlorenen Landen und vom Basar.": "Henüz yumurta yok. İlki hikâyenin ilk bossundan gelir; diğerleri bosslardan, Ejder Sandığı'ndan, Kayıp Diyarlar'dan ve Pazar'dan.",
