  "Heiltotem": "Şifa Totemi",
  "Ein eisiger Ring um den Boss friert ein, wer drinsteht. Raus aus dem Kreis!": "Bossun etrafındaki buzdan halka, içinde duranı dondurur. Çemberden çık!",
  "Meteorregen": "Meteor Yağmuru",
  "Brennende Felsen fallen vom Himmel. Die Kreise zeigen, wo sie einschlagen.": "Gökten yanan kayalar düşer. Çemberler nereye çarpacaklarını gösterir.",
  "Schockwellen": "Şok Dalgaları",
  "Der Boss stampft – Wellen rollen nach außen. Rolle durch die Welle oder bleib außer Reichweite.": "Boss yere tepinir – dalgalar dışa doğru yayılır. Dalganın içinden takla at ya da menzil dışında kal.",
  "Tipp: Während du rollst, kann dich nichts treffen – rolle durch Wellen hindurch!": "İpucu: Takla atarken hiçbir şey sana isabet edemez – dalgaların içinden takla at!",
  "Eine Bahn zeigt, wohin der Boss gleich stürmt. Geh zur Seite!": "Bir şerit, bossun birazdan nereye hücum edeceğini gösterir. Kenara çekil!",
  "Beschwörung": "Çağırma",
  "Aus Portalen kriechen Diener. Erledige sie, bevor es zu viele werden.": "Geçitlerden uşaklar sürünerek çıkar. Çoğalmadan onları hallet.",
  "Schutzschild": "Koruma Kalkanı",
  "Ein Schild schluckt viel Schaden. Brich ihn – dann ist der Boss kurz benommen.": "Bir kalkan çok hasar emer. Onu kır – boss kısa süre sersemler.",
  "Tipp: Brich den Schild – dann ist der Boss ein paar Sekunden benommen.": "İpucu: Kalkanı kır – boss birkaç saniye sersemler.",
  "Der Boss verschwindet und taucht am markierten Ort wieder auf – mit einem Schlag.": "Boss kaybolur ve işaretli yerde yeniden belirir – hem de bir darbeyle.",
  "Giftwolken": "Zehir Bulutları",
  "Giftblasen platzen und hinterlassen Wolken, die lange brennen.": "Zehir kabarcıkları patlar ve uzun süre yakan bulutlar bırakır.",
  "Blitzschlag": "Yıldırım Çarpması",
  "Ein Zeichen folgt dir und bleibt dann stehen – lauf weg, bevor der Blitz einschlägt.": "Bir işaret seni izler, sonra durur – yıldırım düşmeden kaç.",
  "Tipp: Das Zeichen folgt dir – sobald es stehen bleibt, lauf weg!": "İpucu: İşaret seni izler – durduğu anda kaç!",
  "Atemstoß": "Nefes Darbesi",
  "Ein Fächer vor dem Boss wird gleich in Feuer, Eis oder Gift getaucht. Geh hinter ihn oder zur Seite.": "Bossun önündeki yelpaze biçimli alan birazdan ateşe, buza ya da zehre bulanır. Arkasına ya da yanına geç.",
  "Todessprung": "Ölüm Sıçrayışı",
  "Der Boss springt dorthin, wo du stehst. Der Schatten am Boden zeigt die Landung.": "Boss senin durduğun yere sıçrar. Yerdeki gölge nereye ineceğini gösterir.",
  "Kugelring": "Küre Halkası",
  "Ein Ring aus Geschossen fliegt nach außen. Stell dich in eine Lücke.": "Mermilerden bir halka dışa doğru uçar. Bir boşluğa geç.",
  "Kreuzschnitt": "Çapraz Kesik",
  "Leuchtende Linien durch den Boss werden gleich zu Klingen. Weg von den Linien!": "Bossun içinden geçen parlak çizgiler birazdan bıçağa dönüşür. Çizgilerden uzak dur!",
  "Erdspalten": "Yer Yarıkları",
  "Der Boden reißt vom Boss in deine Richtung auf. Geh aus der Spur.": "Zemin bosstan sana doğru yarılır. Yarığın yolundan çekil.",
  "Klingenwirbel": "Kılıç Girdabı",
  "Klingen kreisen um den Boss. Erst sind sie blass – dann schneiden sie.": "Bossun etrafında kılıçlar döner. Önce soluktur – sonra keserler.",
  "Ein ganzes Feld fängt Feuer. Verlass die markierte Fläche schnell.": "Koca bir alan alev alır. İşaretli alanı hızla terk et.",
  "Lebensraub": "Can Emme",
  "Im Kreis um den Boss saugt er dir Leben aus und heilt sich. Verlass den Kreis.": "Boss, etrafındaki çemberde canını emer ve kendini iyileştirir. Çemberden çık.",
  "Tipp: Verlass den roten Kreis, dann reißt der Lebensraub ab.": "İpucu: Kırmızı çemberden çık, can emme kesilir.",
  "Unter 30 % Leben wird der Boss schneller und stärker.": "Canı %30'un altına düşünce boss hızlanır ve güçlenir.",
  "Phasen": "Evreler",
  "Bei 66 % und 33 % Leben stößt der Boss alle zurück und kämpft danach schneller – manchmal mit neuen Kräften.": "Canı %66 ve %33'e inince boss herkesi geri iter, sonra daha hızlı savaşır – bazen yeni güçlerle.",
  "Seelenjäger": "Ruh Avcıları",
  "Langsame Geister verfolgen dich. Weiche aus oder zerschlag sie mit Nahkampfhieben.": "Yavaş hayaletler peşine düşer. Onlardan kaç ya da yakın dövüş darbeleriyle parçala.",
  "Sprengsaat": "Patlayan Tohum",
  "Der Boss verstreut Minen. Kommst du zu nah, zünden sie – der rote Kreis zeigt die Explosion.": "Boss etrafa mayın saçar. Fazla yaklaşırsan patlarlar – kırmızı çember patlama alanını gösterir.",
  "Der Boss heilt sich. Viel Schaden in kurzer Zeit unterbricht ihn.": "Boss kendini iyileştirir. Kısa sürede çok hasar vermek onu durdurur.",
  "Tipp: Viel Schaden in kurzer Zeit unterbricht die Heilung.": "İpucu: Kısa sürede çok hasar vermek iyileşmeyi keser.",
  "Heiltotems": "Şifa Totemleri",
  "Totems heilen den Boss, solange sie stehen. Zerstöre sie zuerst.": "Totemler ayakta kaldıkça bossu iyileştirir. Önce onları yok et.",
  "Tipp: Die Totems heilen den Boss – zerstöre sie zuerst!": "İpucu: Totemler bossu iyileştirir – önce onları yok et!",
  "Sog": "Çekim",
  "Der Boss zieht dich zu sich – in seiner Mitte wartet Schaden. Lauf dagegen an.": "Boss seni kendine çeker – merkezinde hasar bekler. Ters yöne koş.",
  "Kugelspirale": "Küre Sarmalı",
  "Drehende Arme aus Geschossen. Bewege dich mit der Drehung.": "Mermilerden dönen kollar. Dönüşle birlikte hareket et.",
  "Blitze springen zwischen Punkten um dich herum. Stell dich nicht auf eine Linie.": "Yıldırımlar etrafındaki noktalar arasında sıçrar. Bir çizginin üstünde durma.",
  "Spiegelbilder": "Ayna Suretleri",
  "Trugbilder des Bosses erscheinen. Nur der echte leuchtet und hat den Lebensbalken oben.": "Bossun sahte suretleri belirir. Yalnızca gerçeği parlar ve can çubuğu üsttedir.",
  "Tipp: Nur der echte Boss hat den leuchtenden Rand – die Trugbilder zerfallen schnell.": "İpucu: Parlayan kenar yalnızca gerçek bossta olur – sahte suretler çabucak dağılır.",
  "Todesstrahl": "Ölüm Işını",
  "Eine dünne Linie zeigt den Strahl an – dann dreht er sich durch die Arena. Bleib hinter ihm.": "İnce bir çizgi ışını haber verir – sonra ışın arenada döner. Arkasında kal.",
  "Finsternis": "Karanlık",
  "Alle Lichter erlöschen für ein paar Sekunden. Gefahren leuchten trotzdem.": "Birkaç saniyeliğine tüm ışıklar söner. Tehlikeler yine de parlar.",
  "Tipp: Farbige Flächen zeigen, wo gleich Schaden kommt. Raus da, bevor sie aufleuchten!": "İpucu: Renkli alanlar birazdan nereye hasar geleceğini gösterir. Parlamadan oradan çık!",
