  "Mod gefunden: {mod}": "Mod bulundu: {mod}",
  "Dein erster Mod! Setz ihn an einer Werkbank oder in der Schmiede ein: VERBESSERN → MODS.": "İlk modun! Onu bir Tezgah'ta ya da Demirci'de tak: GELİŞTİR → MODLAR.",
  "{n} G": "{n} A",
  "{p} je Treffer: Kettenblitz auf {n} Gegner, je {v} Waffenschaden": "Her isabette {p} şans: {n} düşmana Zincir Şimşek, her biri {v} silah hasarı",
  "{p} je Treffer: Frostnova um das Ziel ({v} Waffenschaden), friert {s} s ein": "Her isabette {p} şans: hedefin çevresinde Buz Novası ({v} silah hasarı), {s} sn dondurur",
  "Jeder Kill heilt {v} deiner LP": "Her öldürme {v} Can yeniler",
  "{p} je Kill: ein Geist kämpft {s} s mit": "Her öldürmede {p} şans: bir hayalet {s} sn yanında savaşır",
  "{p} je Treffer: Blutung, 4 s lang je Sekunde {v} Waffenschaden": "Her isabette {p} şans: kanama, 4 sn boyunca saniyede {v} silah hasarı",
  "{p} je Kill: der Gegner explodiert ({v} Waffenschaden ringsum)": "Her öldürmede {p} şans: düşman patlar (çevreye {v} silah hasarı)",
  "{p} je kritischem Treffer: ein Meteor schlägt ein ({v} Waffenschaden)": "Her kritik vuruşta {p} şans: bir meteor düşer ({v} silah hasarı)",
  "{p} je Treffer: eine Schattenklinge trifft noch einmal ({v} Waffenschaden)": "Her isabette {p} şans: bir gölge kılıcı bir kez daha vurur ({v} silah hasarı)",
  "Wirst du getroffen: Druckwelle mit {v} Waffenschaden, höchstens alle {s} s": "Vurulduğunda: {v} silah hasarlı şok dalgası, en fazla her {s} sn'de bir",
  "{p} je kritischem Treffer: Klingenwirbel um dich, 1,4 s lang je {v} Waffenschaden": "Her kritik vuruşta {p} şans: etrafında Kılıç Girdabı, 1,4 sn boyunca her biri {v} silah hasarı",
