  "Waffe: Element {el} für alle Treffer, +{v} Schaden und Effekt-Chance": "Silah: tüm vuruşlar {el} elementi, +{v} hasar ve efekt şansı",
  "Rüstung/Helm: {el}-Schutz, −{v} Schaden von {el}-Gegnern": "Zırh/Miğfer: {el} koruması, {el} düşmanlarından −{v} hasar",
  "Für Waffen – unter UMSCHMIEDEN einsetzen": "Silahlar için – YENİDEN DÖV bölümünde tak",
  "Für Rüstung und Helm – unter UMSCHMIEDEN einsetzen": "Zırh ve miğfer için – YENİDEN DÖV bölümünde tak",
  "Flammenregen": "Alev Yağmuru",
  "Die Sternglyphe ruft drei brennende Meteore statt einem.": "Yıldız Glifi bir yerine üç yanan meteor çağırır.",
  "Ein fallender Stern trifft auf Feuer …": "Düşen bir yıldız ateşle buluşur …",
  "Frostfessel": "Buz Prangası",
  "Frostnova +50 % Radius, hält auch Bosse kurz fest. Gefrorene und gekühlte Gegner erleiden +{v} Schaden.": "Buz Novası +%50 yarıçap, bossları da kısa süre tutar. Donmuş ve soğutulmuş düşmanlar +{v} hasar alır.",
  "Kälte, die nicht mehr loslässt.": "Bir daha bırakmayan soğuk.",
  "Gewitterklinge": "Fırtına Kılıcı",
  "Der Kettenblitz springt 2 Mal weiter und lädt 40 % schneller.": "Zincir Şimşek 2 kez daha sıçrar ve %40 daha hızlı dolar.",
  "Blitz in der Klinge, Blitz in der Kette.": "Kılıçta yıldırım, zincirde yıldırım.",
  "Seelenernte": "Ruh Hasadı",
  "Alle 12 Kills ein Seelenstoß: heilt {v} LP und ruft einen Geist.": "Her 12 öldürmede bir ruh dalgası: {v} Can yeniler ve bir hayalet çağırır.",
  "Leben und Geister im selben Stück.": "Aynı eşyada yaşam ve hayaletler.",
  "Blutungen machen 50 % mehr Schaden. Kritische Treffer gegen Blutende heilen {v} LP.": "Kanamalar %50 daha fazla hasar verir. Kanayan düşmanlara kritik vuruşlar {v} Can yeniler.",
  "Blut und Zorn unter rotem Mond.": "Kızıl ayın altında kan ve gazap.",
  "Giftnebel": "Zehir Sisi",
  "Gesprengte Gegner hinterlassen 3 s eine Giftwolke.": "Patlayan düşmanlar 3 sn boyunca bir zehir bulutu bırakır.",
  "Wenn Gift auf eine Explosion trifft …": "Zehir bir patlamayla buluşunca …",
  "Schattentanz": "Gölge Dansı",
  "Jede Schattenklinge gibt dir 2 s lang +{v} Tempo.": "Her gölge kılıcı sana 2 sn boyunca +{v} hız verir.",
  "Schatten, die schnell tanzen.": "Hızlı dans eden gölgeler.",
  "Lichtschild": "Işık Kalkanı",
  "Alle 10 s ein Lichtschild, der {v} deiner LP an Schaden schluckt.": "Her 10 sn'de bir, Can'ının {v} kadar hasarı emen bir ışık kalkanı.",
  "Licht und Stein schützen den Leib.": "Işık ve taş bedeni korur.",
  "Dornenhaut": "Dikenli Deri",
  "Vergeltung trifft den Angreifer zusätzlich mit dem doppelten Schaden und lädt 1,5 s schneller.": "Misilleme saldırgana ayrıca iki kat hasarla vurur ve 1,5 sn daha hızlı dolar.",
  "Wer zurückschlägt, braucht eine harte Haut.": "Karşılık veren, kalın bir deriye ihtiyaç duyar.",
  "Sturmlauf": "Fırtına Koşusu",
  "Nach jeder Rolle und Bewegungs-Fähigkeit 3 s lang +25 % Lauftempo und +{v} Schaden.": "Her taklanın ve hareket yeteneğinin ardından 3 sn boyunca +%25 koşu hızı ve +{v} hasar.",
  "Wind unter den Füßen eines Springers.": "Bir sıçrayanın ayaklarının altında rüzgâr.",
  "Phönixfunke": "Anka Kıvılcımı",
  "Fällst du unter 30 % LP: Feuerstoß und {v} LP zurück – einmal pro Minute.": "Canın %30'un altına düşünce: ateş patlaması ve {v} Can geri – dakikada bir kez.",
  "Feuer, das Leben zurückgibt.": "Hayatı geri veren ateş.",
  "Eiserne Wacht": "Demir Nöbet",
  "Du erleidest {v} weniger Schaden.": "{v} daha az hasar alırsın.",
  "Stein und Leben in einem Panzer.": "Tek bir zırhta taş ve yaşam.",
  "Arkane Flut": "Arkan Akın",
  "Jede 4. Fähigkeit kostet nichts und lädt doppelt so schnell.": "Her 4. yetenek bedavadır ve iki kat hızlı dolar.",
  "Fluss und Fokus vereint.": "Akış ve odak bir arada.",
  "Jede Leichensprengung entfesselt einen Kettenblitz.": "Her ceset patlaması bir Zincir Şimşek salar.",
