  "DAS TOR ÖFFNET SICH …": "KAPI AÇILIYOR …",
  "Das Tor flackert – versuch es noch einmal.": "Kapı titreşiyor – bir daha dene.",
  "Tipp: Je weiter du dich vom Weltentor entfernst, desto stärker die Gegner – und desto besser die Beute.": "İpucu: Dünya Kapısı'ndan ne kadar uzaklaşırsan düşmanlar o kadar güçlenir – ganimet de o kadar iyileşir.",
  "Dein letzter Ausflug endete mitten im Kampf – die Lande haben dich verschlungen. Ausrüstung und Rucksack sind verloren.": "Son seferin savaşın ortasında sona erdi – diyarlar seni yuttu. Ekipman ve sırt çantası kayboldu.",
  "Dein letzter Ausflug in die Endlosen Lande wurde unterbrochen: Der Rucksack ist verloren, deine Ausrüstung vom Aufbruch hast du noch.": "Sonsuz Topraklar'a son seferin yarıda kesildi: Sırt çantası kayboldu, ama yola çıktığın ekipman hâlâ sende.",
  "Dein Begleiter hat noch Beute aus den Landen dabei – sie liegt jetzt bei dir.": "Yoldaşın Diyarlar'dan hâlâ ganimet taşıyordu – artık sende.",
  "AUFTRÄGE ERFÜLLT": "GÖREVLER TAMAMLANDI",
