  "{name} ist verletzt und braucht etwa {n} Minuten Ruhe.": "{name} yaralı ve yaklaşık {n} dakika dinlenmesi gerek.",
  "Hardcore kennt keine Gnade. {name} ist in den Endlosen Landen gefallen und steht nun in der Ruhmeshalle.": "Hardcore acımaz. {name} Sonsuz Topraklar'da düştü ve artık Onur Listesi'nde.",
  "Dein Begleiter hat {n} Dinge ins Lager gerettet.": "Yoldaşın {n} eşyayı depoya kurtardı.",
  "Zum Titel": "Ana menüye",
  "GERETTET VON {name}": "KURTARAN: {name}",
  "Die Begleiter-Tasche war leer – nichts wurde gerettet.": "Yoldaş Çantası boştu – hiçbir şey kurtarılamadı.",
  "Ohne Begleiter wurde nichts gerettet. Ein Begleiter trägt eine Tasche, die deinen Tod übersteht.": "Yoldaşın olmadığı için hiçbir şey kurtarılamadı. Yoldaşlar, ölümünden sonra da korunan bir çanta taşır.",
  "Was du seit dem letzten Leuchtfeuer erkundet hast ({n} Regionen), ist vergessen.": "Son işaret ateşinden beri keşfettiklerin ({n} yöre) unutuldu.",
  "Du erwachst im Versteck – mit einfacher Ausrüstung. Schmiede neue oder hol sie dir aus Beutel und Lager.": "Sığınakta uyanıyorsun – basit bir ekipmanla. Yenisini döv ya da çantandan ve depodan al.",
