  "Belohnung bei einer Kundschafterin abholen – oder sie kommt beim Ausgang mit.": "Ödülünü bir izciden al – ya da çıkışta kendiliğinden gelir.",
  "Hier endet die Welt. Dahinter ist nur noch das Nichts.": "Dünya burada biter. Ötesinde yalnızca yokluk var.",
