  "In den Rucksack": "Sırt çantasına",
  "Wirklich wegwerfen?": "Gerçekten atılsın mı?",
  "Wegwerfen": "At",
  "Wert: {n} Gold": "Değer: {n} altın",
  "sicher in der Tasche": "çantada güvende",
  "geht beim Tod verloren": "ölünce kaybolur",
  "BEGLEITER-TASCHE {n}/{max}": "YOLDAŞ ÇANTASI {n}/{max}",
  "{name} bringt das heim – auch wenn du fällst.": "{name} bunları eve getirir – düşsen bile.",
  "Keine Plätze.": "Yer yok.",
  "Kein Begleiter dabei: Stirbst du, ist alles verloren.": "Yanında yoldaş yok: Ölürsen her şey kaybolur.",
  "Ohne Begleiter-Tasche: Stirbst du, ist alles verloren.": "Yoldaş Çantası yok: Ölürsen her şey kaybolur.",
  "RUCKSACK {n}/{max}": "SIRT ÇANTASI {n}/{max}",
  "Wirklich {n} wegwerfen?": "Gerçekten {n} eşya atılsın mı?",
  "Plunder wegwerfen ({n})": "Hurdayı at ({n})",
  "Rückkehrrolle lesen ({n})": "Dönüş Parşömeni oku ({n})",
  "{n} Dinge weggeworfen": "{n} eşya atıldı",
  "Ein Rückweg öffnet sich unter deinen Füßen – bleib stehen!": "Ayaklarının altında bir dönüş yolu açılıyor – kıpırdama!",
  "MITTEN IM KAMPF!": "SAVAŞIN ORTASINDASIN!",
  "Abbrechen geht nur, wenn dich gerade nichts angreift. Lauf weg oder kämpfe!": "Sadece sana şu an kimse saldırmıyorsa iptal edebilirsin. Kaç ya da savaş!",
  "AUSFLUG ABBRECHEN?": "SEFER İPTAL EDİLSİN Mİ?",
  "Der Rucksack bleibt in den Landen, und was du seit dem letzten Leuchtfeuer erkundet hast, ist vergessen. Du behältst die Ausrüstung, mit der du aufgebrochen bist, und alles in der Begleiter-Tasche.": "Sırt çantası topraklarda kalır ve son işaret ateşinden beri keşfettiklerin unutulur. Yola çıktığın ekipman ve Yoldaş Çantası'ndaki her şey sende kalır.",
  "Ja, abbrechen": "Evet, iptal et",
  "Weiter erkunden": "Keşfe devam",
  "Ausflug abgebrochen – {n} Dinge sind verloren.": "Sefer iptal edildi – {n} eşya kayboldu.",
  "Ausflug abgebrochen.": "Sefer iptal edildi.",
  "Du hast keinen Leuchtfeuerstein. Sie liegen selten in Truhen, bei Bossen und bei Händlern.": "İşaret Taşın yok. Nadiren sandıklarda, bosslarda ve tüccarlarda bulunur.",
  "Nicht mitten im Kampf!": "Savaşın ortasında olmaz!",
  "Hier ist kein fester Boden.": "Burada sağlam zemin yok.",
  "Zu nah an einem Ausgang, Lager oder Leuchtfeuer.": "Bir çıkışa, kampa ya da işaret ateşine çok yakın.",
  "LEUCHTFEUER SETZEN": "İŞARET ATEŞİ KUR",
  "{n} STEINE": "{n} TAŞ",
  "Ein Leuchtfeuer kostet einen Leuchtfeuerstein und brennt für immer.": "Bir işaret ateşi bir İşaret Taşı'na mal olur ve sonsuza dek yanar.",
  "Die Karte bis hierher wird gesichert – auch wenn du später fällst.": "Buraya kadarki harita kaydedilir – sonradan düşsen bile.",
  "Beim nächsten Ausflug kannst du hier starten.": "Bir sonraki seferde buradan başlayabilirsin.",
  "Es ist ein Ausgang: hineinstellen und warten – die Beute ist sicher.": "Aynı zamanda bir çıkış: içine gir ve bekle – ganimet güvende.",
  "{d} vom Weltentor": "Dünya Kapısı'ndan {d}",
  "Du hast schon {n} Leuchtfeuer – das am längsten unbenutzte erlischt: {name}": "Zaten {n} işaret ateşin var – en uzun süredir kullanılmayan sönecek: {name}",
