  "Karte gesichert ({n} neue Regionen). Hier startest du beim nächsten Mal – und hier kommst du raus.": "Harita kaydedildi ({n} yeni yöre). Bir dahaki sefere buradan başlarsın – ve buradan dışarı çıkabilirsin.",
  "Leuchtfeuer / Ausgang": "İşaret Ateşi / Çıkış",
