  "für dich {r}": "senin için {r}",
  "{d} vom Weltentor · Tiefe {p} %": "Dünya Kapısı'ndan {d} · Derinlik %{p}",
  "Regionen entdeckt: {n} · weiteste Reise: {d}": "Keşfedilen yöre: {n} · en uzak yolculuk: {d}",
