  "NOCH UNERFORSCHT": "HENÜZ KEŞFEDİLMEDİ",
  "{d} breit": "Genişlik: {d}",
  "Kundschafterinnen in den Außenposten haben Aufträge für dich.": "Karakollardaki izcilerin sana görevleri var.",
  "AUFTRÄGE": "GÖREVLER",
  "Belohnung: {rep} Ruf, {items}": "Ödül: {rep} itibar, {items}",
  "Schlüssel": "Anahtar",
  "Belohnung nehmen": "Ödülü al",
  "Gerücht über eine Spur": "Bir ize dair söylenti",
  "Tipp: Erfüllte Aufträge zahlen hier – oder automatisch, wenn du lebend durch einen Ausgang gehst.": "İpucu: Tamamlanan görevlerin ödülü burada ödenir – ya da bir çıkıştan sağ çıkınca otomatik olarak.",
  "Gerücht: {tool}": "Söylenti: {tool}",
  "Ein Hort mit diesem Werkzeug soll etwa {d} im {dir} liegen. Auf der Karte ist die Gegend markiert.": "Bu aleti barındıran bir mahzenin {dir} yönünde yaklaşık {d} uzakta olduğu söyleniyor. Bölge haritada işaretli.",
  "„Der Orden braucht Augen hier draußen. Erledige, was du kannst – bezahlt wird, wenn du es mir bringst oder lebend durch ein Tor gehst.“": "“Tarikatın buralarda gözlere ihtiyacı var. Ne yapabiliyorsan yap – ödemeyi bana getirdiğinde ya da bir kapıdan sağ geçtiğinde alırsın.”",
  "RUF: {n}": "İTİBAR: {n}",
  "Nächster Rang: {n} – {d}": "Sonraki rütbe: {n} – {d}",
