  "Gib:": "Ver:",
  "Heiltrank": "Can İksiri",
  "Kartenstück": "Harita Parçası",
  "Rückkehrrolle (Ausgang überall, doppelt so lange stehen)": "Dönüş Parşömeni (her yerde çıkış, iki kat uzun bekleme)",
  "Leuchtfeuerstein (einer je Außenposten)": "İşaret Taşı (karakol başına bir tane)",
  "Bezahlt wird mit dem Gold in deinem Rucksack.": "Ödeme sırt çantandaki altınla yapılır.",
  "Leuchtfeuersteine verkaufen Händler erst ab dem Ruf „Bekannter“.": "Tüccarlar İşaret Taşı'nı ancak “Tanıdık” itibarından itibaren satar.",
  "Das Gold kommt in den Rucksack – raustragen musst du es trotzdem.": "Altın sırt çantana gider – yine de onu dışarı taşıman gerek.",
  "Dein Rucksack ist leer.": "Sırt çantan boş.",
  "„Hier draußen zahlt man mit dem, was man trägt. Zeig her, was du hast.“": "“Burada herkes taşıdığıyla öder. Göster bakalım neyin var.”",
  "TAUSCH": "TAKAS",
  "KAUFEN": "AL",
  "VERKAUFEN": "SAT",
  "Rucksack voll!": "Sırt çantası dolu!",
  "Getauscht: {n}": "Takaslandı: {n}",
  "Leuchtfeuerstein gekauft ({n})": "İşaret Taşı alındı ({n})",
  "„Setz dich ans Feuer. Die Lande nehmen viel – ein bisschen gebe ich zurück.“": "“Ateşin başına otur. Diyarlar çok şey alır – birazını ben geri veririm.”",
