  "Tasche mit {n} Plätzen – was darin liegt, überlebt deinen Tod.": "{n} yerlik çanta – içindekiler ölümünden sonra da korunur.",
  "Hat keine Tasche.": "Çantası yok.",
  "{n} PLÄTZE": "{n} YER",
  "{name} ist verletzt": "{name} yaralı",
  "Kein Begleiter dabei": "Yanında yoldaş yok",
  "Ruht sich noch {n} Minuten im Versteck aus.": "{n} dakika daha sığınakta dinleniyor.",
  "Ohne Begleiter-Tasche ist bei deinem Tod alles verloren.": "Yoldaş Çantası olmadan ölürsen her şey kaybolur.",
  "FUNDKISTE ({n})": "BULUNTU SANDIĞI ({n})",
  "Was beim letzten Mal keinen Platz mehr hatte.": "Geçen sefer yer kalmayanlar.",
  "Alles abholen": "Hepsini al",
  "WERKZEUGE {n}/{max}": "ALETLER {n}/{max}",
  "Als Nächstes: {tool} – für {bar} etwa {d} vom Tor. Horte damit liegen diesseits davon.": "Sıradaki: {tool} – kapıdan yaklaşık {d} uzaktaki {bar} için. Onu barındıran mahzenler bu tarafta.",
  "Du hast alle Werkzeuge. Die ganze Welt steht dir offen – bis an ihren Rand.": "Tüm aletler sende. Bütün dünya sana açık – ta kıyısına kadar.",
  "STARTPUNKT": "BAŞLANGIÇ",
  "LEUCHTFEUERSTEINE {n}": "İŞARET TAŞI {n}",
  "LEUCHTFEUER {n}/{max}": "İŞARET ATEŞİ {n}/{max}",
  "SCHLÜSSEL {n}": "ANAHTAR {n}",
  "Karte der Lande": "Toprakların Haritası",
  "WAS DU RISKIERST · {n} GOLD": "RİSKE ATTIĞIN · {n} ALTIN",
  "WAS ÜBERLEBT": "KORUNANLAR",
  "Stirbst du, sind Ausrüstung und Rucksack verloren.": "Ölürsen ekipman ve sırt çantası kaybolur.",
  "Nur die Begleiter-Tasche kommt heim – dein Begleiter teleportiert mit dir zurück.": "Sadece Yoldaş Çantası eve döner – yoldaşın seninle birlikte geri ışınlanır.",
  "Raus kommst du durch ein Tor der Alten, das Weltentor oder ein Leuchtfeuer: hineinstellen und warten.": "Kadimlerin kapılarından birinden, Dünya Kapısı'ndan ya da bir işaret ateşinden dışarı çıkarsın: içine gir ve bekle.",
  "Die Karte wird nur gesichert, wenn du ein Leuchtfeuer setzt oder entkommst – wer fällt, vergisst den Weg seit dem letzten Leuchtfeuer.": "Harita yalnızca bir işaret ateşi kurduğunda ya da kaçtığında kaydedilir – düşen, son işaret ateşinden beri yürüdüğü yolu unutur.",
  "Abbrechen geht nur außerhalb des Kampfes – wer mitten im Kampf das Spiel schließt, fällt.": "İptal sadece savaş dışında mümkün – savaşın ortasında oyunu kapatan düşer.",
  "Noch {n} Ruf bis {r}: {d}": "{r} için {n} itibar kaldı: {d}",
  "AUSFLÜGE {n}": "SEFER {n}",
  "ENTKOMMEN {n}": "KAÇIŞ {n}",
  "GEFALLEN {n}": "ÖLÜM {n}",
  "BESTE BEUTE {n}": "REKOR GANİMET {n}",
  "REGIONEN {n}": "YÖRELER {n}",
  "WEITESTE REISE {d}": "EN UZAK YOL {d}",
  "Betreten: {n}": "Gir: {n}",
  "Ab Level {n} – dir fehlen noch {m}": "Seviye {n} gerekli – {m} seviye eksik",
  "Hinter dem Tor liegen die Endlosen Lande: eine Welt ohne Ende, für alle dieselbe – die beste Beute, aber wer dort stirbt, verliert, was er trägt.": "Kapının ardında Sonsuz Topraklar uzanır: sonu olmayan, herkes için aynı bir dünya – en iyi ganimet orada, ama orada ölen üzerindekileri kaybeder.",
  "DIE ENDLOSEN LANDE": "SONSUZ TOPRAKLAR",
  "Die beste Beute – aber wer dort stirbt, verliert, was er trägt.": "En iyi ganimet – ama orada ölen, taşıdığını kaybeder.",
  "{n} Dinge abgeholt": "{n} eşya alındı",
  "Endlose Lande": "Sonsuz Topraklar",
  "ab LV 5": "LV 5+",
  "Torhüterin Ysra": "Kapı Bekçisi Ysra",
  "Hinter dem Tor liegen die Endlosen Lande. Wer dort fällt, kommt nackt zurück – wenn überhaupt.": "Kapının ardında Sonsuz Topraklar uzanır. Orada düşen çırılçıplak döner – tabii dönebilirse.",
  "Nimm deinen Begleiter mit. Was in seiner Tasche steckt, bringt er immer heim.": "Yoldaşını yanına al. Çantasındakileri her zaman eve getirir.",
  "Je weiter du gehst, desto härter wird es. Ein Leuchtfeuer sichert den Weg, den du gegangen bist.": "Ne kadar ileri gidersen o kadar zorlaşır. Bir işaret ateşi yürüdüğün yolu kaydeder.",
  "Schluchten, Flüsse, Giftnebel … ohne das richtige Werkzeug kommst du nicht weiter. Die Kundschafterinnen wissen, wo eins liegt.": "Uçurumlar, nehirler, zehir sisi … doğru alet olmadan ilerleyemezsin. İzciler nerede bir tane olduğunu bilir.",
  "Frühbieter": "Erkenci",
  "Stetig": "İstikrarlı",
  "Last-Minute": "Son Dakikacı",
  "Sammler": "Koleksiyoncu",
  "Schnäppchenjäger": "Fırsat Avcısı",
  "Krämer": "Çerçi",
  "Kaufmann": "Bezirgân",
  "Großhändler": "Toptancı",
  "Handelsherr": "Ticaret Beyi",
  "Gildenmeister": "Lonca Ustası",
  "Magnat": "Baron",
  "Basarfürst": "Pazar Prensi",
