  "Legende des Basars": "Pazarın Efsanesi",
  "Auktionatorin Hedda": "Mezatçı Hedda",
  "Alles hat seinen Preis, {name}. Die Kunst ist, ihn vor den anderen zu kennen.": "Her şeyin bir fiyatı vardır, {name}. Asıl hüner, onu herkesten önce bilmektir.",
  "Kaspar bietet immer in der letzten Minute. Halt die Augen offen.": "Kaspar hep son dakikada teklif verir. Gözünü dört aç.",
  "Wer versteigert, braucht Geduld. Wer bietet, braucht Nerven.": "Mezata koyan sabır ister. Teklif veren sağlam sinir.",
  "Ein Legendärer unter Marktwert? Kommt vor. Selten. Aber es kommt vor.": "Piyasa değerinin altında bir Efsanevi mi? Olur. Nadiren. Ama olur.",
  "Grimbart sammelt alles, was glänzt – und zahlt dafür fast jeden Preis.": "Grimbart parlayan her şeyi toplar – ve bunun için neredeyse her fiyatı öder.",
  "Mein Hammer fällt, wenn die Zeit um ist. Keine Sekunde früher.": "Süre dolunca tokmağım iner. Bir saniye bile erken değil.",
  "Marktwert: {n} Gold": "Piyasa değeri: {n} altın",
  "Handelsrang {n}: {title}! Weniger Gebühr, mehr Plätze.": "Ticaret rütbesi {n}: {title}! Daha az komisyon, daha çok yer.",
  "Bauteil für die Schmiede": "Demirci için bileşen",
