  "Du wurdest überboten! {item}: {name} bietet {n} Gold.": "Teklifin geçildi! {item}: {name} {n} altın teklif ediyor.",
  "Zuschlag! {item} für {n} Gold ersteigert – im Abholfach.": "Kazandın! {item} mezattan {n} altına senin – teslim kutusunda.",
  "Verkauft! {item} an {name} für {n} Gold.": "Satıldı! {name}, {item} için {n} altın ödedi.",
  "Nicht verkauft: {item} – liegt im Abholfach.": "Satılmadı: {item} – teslim kutusunda.",
  "Neues Gebot auf {item}: {n} Gold von {name}.": "{item} için yeni teklif: {n} altın ({name}).",
  "Versteigerung verloren: {item} ging für {n} Gold an {name}.": "Mezatı kaybettin: {item}, {n} altına {name} tarafından alındı.",
  "Basar: {n} weitere Neuigkeiten – siehe MEINE.": "Pazar: {n} haber daha – BENİM sekmesine bak.",
  "ZUSCHLAG!": "KAZANDIN!",
  "VERKAUFT!": "SATILDI!",
  "Zu wenig Gold.": "Yetersiz altın.",
  "Beutel und Lager sind voll. Mach zuerst Platz.": "Çanta ve depo dolu. Önce yer aç.",
  "Dein Brutnest ist voll.": "Kuluçka Yuvan dolu.",
  "Eier kann diese Version noch nicht annehmen.": "Bu sürüm henüz yumurta kabul edemiyor.",
  "Das ist nicht mehr da.": "Bu artık yok.",
  "Diese Versteigerung ist schon vorbei.": "Bu mezat çoktan bitti.",
  "Du hast schon das höchste Gebot.": "En yüksek teklif zaten senin.",
  "Das Gebot ist zu niedrig.": "Teklif çok düşük.",
  "Alle Auktionsplätze sind belegt. Ein höherer Handelsrang bringt mehr.": "Tüm mezat yerleri dolu. Daha yüksek ticaret rütbesi daha fazla yer getirir.",
  "Wähle zuerst einen Helden.": "Önce bir kahraman seç.",
  "Es gibt schon Gebote – die Versteigerung läuft bis zum Ende.": "Zaten teklifler var – mezat sonuna kadar sürer.",
  "{item} liegt im Beutel.": "{item} çantanda.",
