  "Die Uhr deines Geräts wurde zurückgestellt. Der Basar wartet, bis sie wieder stimmt (noch {t}).": "Cihazının saati geri alınmış. Pazar, saat yeniden doğru olana kadar bekliyor ({t} kaldı).",
