  "AUSVERKAUFT": "TÜKENDİ",
  "Tippe ein Angebot an, um es genau anzusehen. Gekauftes kommt in den Beutel – ist er voll, ins Lager.": "Ayrıntılı görmek için bir ilana dokun. Satın aldıkların çantaya gider – doluysa depoya.",
