  "MATERIAL": "MALZEME",
  "Sofort verkaufen bringt Gold auf die Hand. Versteigern bringt meist mehr – dauert aber.": "Hemen satmak eline anında altın verir. Mezata koymak genelde daha çok getirir – ama zaman alır.",
