  "Die Gerüste dort? Dort bauen wir Schmiede, Labor, Schatzkammer und mehr. Geh hin und sieh, was es kostet.": "Şu iskeleler mi? Orada demirci, simya atölyesi, hazine odası ve daha fazlasını kuracağız. Git de neye mal olduğuna bir bak.",
