  "Chronikseiten findest du in Truhen, bei Elite-Gegnern, Bossen und in Gräbern. Ab Bibliothek-Stufe 3 häufiger.": "Tarihçe sayfalarını sandıklarda, Elit düşmanlarda, bosslarda ve mezarlarda bulursun. Kütüphane Seviye 3'ten itibaren daha sık.",
