  "SCHICKSALSTRUHEN": "KADER SANDIKLARI",
  "Glücksmünzen gibt es von Bossen, Champions, seltenen Truhen, der Tages-Challenge und Schreinen Fortunas. Jede Drehung ist reiner Zufall mit den gezeigten Chancen – Mythisch kann beim ersten Dreh kommen oder erst nach sehr vielen.": "Şans Sikkeleri bosslardan, şampiyonlardan, nadir sandıklardan, Günlük Mücadele'den ve Fortuna Tapınaklarından gelir. Her çeviriş gösterilen şanslarla tamamen rastgeledir – Mitik ilk çevirişte de gelebilir, çok sonra da.",
