  "nicht für deine Klasse": "sınıfına uygun değil",
  "STEUERUNG": "KONTROLLER",
  "Linke Seite ziehen: laufen. Angriff halten (3er-Kombo) – über den Knopf wischen zielt von Hand. Rolle, drei Fähigkeiten, Ultimative (goldene Wut-Leiste). Der Trank sitzt links oben. Alle Knöpfe lassen sich unter Einstellungen → Steuerung verschieben.": "Sol tarafı sürükle: yürü. Saldırıyı basılı tut (3'lü kombo) – tuşun üstünde kaydırarak elle nişan al. Takla, üç yetenek, Nihai (altın Öfke çubuğu). İksir sol üstte. Tüm tuşları Ayarlar → Kontroller bölümünden taşıyabilirsin.",
  "WASD laufen · J/Leertaste/Klick angreifen · K/Shift ausweichen · 1 2 3 Fähigkeiten · F Ultimative · H Trank · E Interagieren · C Charakter · Esc Pause": "WASD yürü · J/Boşluk/Tık saldır · K/Shift kaç · 1 2 3 yetenekler · F Nihai · H iksir · E etkileşim · C karakter · Esc duraklat",
  "Grafik: „16x16 DungeonTileset II“ von 0x72, Zauber-Effekte „Pixel Art Spells“, „Pixel Art Sword Slash“ und Explosionen von OpenGameArt – alle CC0.": "Grafik: 0x72'den “16x16 DungeonTileset II”, OpenGameArt'tan büyü efektleri “Pixel Art Spells”, “Pixel Art Sword Slash” ve patlamalar – hepsi CC0.",
